import {Browser} from '../../src/browser.js';
const browser=new Browser({timeout:200});let page;
try{page=browser.createPage();await page.navigate('data:text/html,<body>actual initial bytes');let timeout=false;
 try{page.evaluate('document.open();globalThis.badLoad=function(event){globalThis.savedLoad=event;while(true){}};addEventListener("load",badLoad);document.write("<p id=actual>first actual bytes</p>");document.close()')}catch(error){timeout=error.code==='ERR_SCRIPT_EXECUTION_TIMEOUT';if(!timeout)throw error}
 await new Promise(resolve=>setImmediate(resolve));const first=page.evaluate('({body:document.getElementById("actual").textContent,eventState:{phase:savedLoad.eventPhase,currentTarget:savedLoad.currentTarget===null,path:savedLoad.composedPath().length,currentEvent:window.event==null}})');const redispatch=page.evaluate('removeEventListener("load",badLoad);dispatchEvent(savedLoad)');const second=page.evaluate('document.open();globalThis.secondLoads=0;addEventListener("load",()=>secondLoads++);document.write("<p id=actual>second actual bytes</p>");document.close();({secondBody:document.getElementById("actual").textContent,secondLoads})');page.close();console.log(JSON.stringify({timeout,...first,redispatch,...second,closed:page.closed}));}finally{browser.close()}
